import { z } from 'zod';
import { POWER_CLASSES } from '../domain/hero.model';

/**
 * Hero edit form. The schema is the single source of truth for the shape, the
 * rules, and the field labels; the form reads its labels off `.meta()`.
 */
export const heroEditSchema = z.object({
  name: z.string().trim().min(1).meta({ label: 'Hero name', control: 'text', order: 1 }),
  alias: z.string().trim().min(1).meta({ label: 'Alias', control: 'text', order: 2 }),
  powerClass: z.enum(POWER_CLASSES).meta({
    label: 'Power class',
    control: 'select',
    order: 3,
    options: POWER_CLASSES.map((value) => ({ value, label: value })),
  }),
  powerIndex: z.number().int().min(0).max(100).meta({ label: 'Power index', control: 'number', order: 4 }),
  notes: z.string().max(1000).meta({ label: 'Notes', control: 'textarea', order: 5 }),
  active: z.boolean().meta({ label: 'Active', control: 'switch', order: 6 }),
});

export type HeroModel = z.infer<typeof heroEditSchema>;

